// Typed access to the design tokens generated by `npm run build` (scripts/tokens.config.mjs).
import raw from './tokens.json'

export type TextStyle = {
  tamanho: number
  alturaLinha: number
  peso: number
  pesoNome: string
  espacamento: number
  caixa: string
}

type SemanticToken = { ref: string; hex: string }

type Tokens = {
  brand: Record<string, string>
  ramps: Record<string, Record<string, string>>
  anchors: Record<string, number | null>
  semantic: Record<string, Record<string, SemanticToken>>
  icons: Record<string, Record<string, SemanticToken>>
  contrast: { fg: string; bg: string; ratio: number; nivel: string; proibido: boolean }[]
  webScale: { base: number; ratio: number }
  webType: Record<string, TextStyle>
  displayRatio: number
  displayType: Record<string, { unidade: string; descricao: string; estilos: Record<string, TextStyle> }>
  spacing: Record<string, number>
  radius: Record<string, number>
  shadows: Record<string, unknown>
}

export const tokens = raw as unknown as Tokens

export const LINKS = {
  repo: 'https://github.com/josegoulartjr/asmube-design-system',
  figma: 'https://www.figma.com/design/rD9NfstRMYqhZDeKthxet9',
  tokensJson: 'https://github.com/josegoulartjr/asmube-design-system/blob/main/tokens/asmube.tokens.json',
  tokensCss: 'https://github.com/josegoulartjr/asmube-design-system/blob/main/css/tokens.css',
  skill: 'https://github.com/josegoulartjr/asmube-design-system/tree/main/skill/asmube-design-system',
  layouts: 'https://github.com/josegoulartjr/asmube-design-system/blob/main/docs/padroes-de-layout.md',
  email: 'https://github.com/josegoulartjr/asmube-design-system/blob/main/email/modelo-email.html',
}

export const BASE = import.meta.env.BASE_URL

// Readable text color for a swatch: dark text on light colors, white on dark ones.
export function textOn(hex: string): string {
  const n = parseInt(hex.slice(1), 16)
  const luminance = ((n >> 16) & 255) * 0.299 + ((n >> 8) & 255) * 0.587 + (n & 255) * 0.114
  return luminance > 150 ? tokens.ramps.neutro['900'] : '#FFFFFF'
}
